"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["83254"],{2211(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.hipotese_legal_invalida","status":422,"titulo":"Hip\xf3tese legal de tratamento do fato fora do vocabul\xe1rio fechado"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.hipotese_legal_invalida","requisitos":["UNI-REQ-0143","UNI-REQ-0159"],"oQueAconteceu":["O administrador cadastrou um fato do cat\xe1logo (declarado, derivado ou resumo de grupo) ou alterou a defini\xe7\xe3o de um fato (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) com uma hip\xf3tese legal de tratamento (`hipoteseLegal`) que n\xe3o pertence ao vocabul\xe1rio fechado. A hip\xf3tese legal \xe9 a base da LGPD que autoriza o tratamento do dado (UNI-REQ-0143 e UNI-REQ-0159).","A recusa vem na lista `errors` da resposta, com `field` igual a `hipoteseLegal`. Nada \xe9 gravado.","Um campo vazio ou s\xf3 com espa\xe7os n\xe3o cai aqui: ele recebe [a recusa de hip\xf3tese legal obrigat\xf3ria](/erros/uniplus.configuracao.fato_candidato.hipotese_legal_obrigatoria). O campo ausente do corpo \xe9 recusado antes, como erro de requisi\xe7\xe3o (400). A compara\xe7\xe3o \xe9 exata: c\xf3digos com espa\xe7os nas pontas s\xe3o recusados."],"comoResolver":["Envie de novo o cadastro ou a defini\xe7\xe3o com uma destas hip\xf3teses, escrita exatamente assim, em mai\xfasculas e com sublinhado (a compara\xe7\xe3o diferencia mai\xfasculas de min\xfasculas):","- `CONSENTIMENTO`;\\n- `CUMPRIMENTO_OBRIGACAO_LEGAL`;\\n- `EXECUCAO_POLITICAS_PUBLICAS`;\\n- `ESTUDOS_POR_ORGAO_DE_PESQUISA`;\\n- `EXECUCAO_CONTRATO`;\\n- `EXERCICIO_REGULAR_DE_DIREITOS`;\\n- `PROTECAO_DA_VIDA`;\\n- `TUTELA_DA_SAUDE`;\\n- `INTERESSE_LEGITIMO`;\\n- `PROTECAO_DO_CREDITO`;\\n- `PREVENCAO_A_FRAUDE`.","Nem toda hip\xf3tese serve a toda classifica\xe7\xe3o: para um fato `SENSIVEL` valem as hip\xf3teses do art. 11 da LGPD, e para os demais valem as do art. 7\xba. S\xf3 o art. 7\xba prev\xea `EXECUCAO_CONTRATO`, `INTERESSE_LEGITIMO` e `PROTECAO_DO_CREDITO`; s\xf3 o art. 11 prev\xea `PREVENCAO_A_FRAUDE`. Uma hip\xf3tese do vocabul\xe1rio que n\xe3o cabe na classifica\xe7\xe3o recebe outra recusa, [a hip\xf3tese legal que n\xe3o cabe na classifica\xe7\xe3o](/erros/uniplus.configuracao.fato_candidato.hipotese_legal_incompativel_com_classificacao)."],"ondeAparece":["Cadastro de um fato do cat\xe1logo (declarado, derivado ou resumo de grupo)","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);